// Smoke test: run the exact inline <script> from index.html through init + frames.
const fs = require('fs');
const vm = require('vm');
const html = fs.readFileSync('<WORKSPACE>/meta/muse-spark-1.3/medium/index.html', 'utf8');
const m = html.match(/<script>([\s\S]*)<\/script>/);
if (!m) { console.error('NO_INLINE_SCRIPT'); process.exit(1); }
const src = m[1];

// --- minimal DOM/canvas stubs ---
function gradStub() {
  return { addColorStop() {} };
}
const ctxStub = {
  setTransform() {}, clearRect() {}, save() {}, restore() {},
  beginPath() {}, arc() {}, ellipse() {}, fill() {},
  createRadialGradient: gradStub,
  set globalAlpha(v) {}, get globalAlpha() { return 1; },
  set fillStyle(v) {}, get fillStyle() { return ''; },
  set globalCompositeOperation(v) {}, get globalCompositeOperation() { return 'source-over'; },
};
function elStub(name) {
  return {
    style: {},
    clientWidth: 1280, clientHeight: 800,
    width: 0, height: 0,
    getContext: () => ctxStub,
    getBoundingClientRect: () => ({ left: 320, top: 200, width: 500, height: 400 }),
    addEventListener() {},
    setAttribute() {},
  };
}
const els = { stage: elStub('stage'), tilt: elStub('tilt'), halo: elStub('halo'), brothShine: elStub('s'), steam: elStub('canvas') };
let rafQueue = [];
const sandbox = {
  console,
  performance: { now: () => 0 },
  requestAnimationFrame: (cb) => { rafQueue.push(cb); return rafQueue.length; },
  window: null,
  document: { getElementById: (id) => els[id] || null },
};
sandbox.window = {
  matchMedia: () => ({ matches: false }),
  addEventListener() {},
  devicePixelRatio: 1,
  innerWidth: 1280, innerHeight: 800,
};
sandbox.globalThis = sandbox;
vm.createContext(sandbox);

// deterministic random for reproducibility
sandbox.Math.random = (() => { let s = 42; return () => (s = (s * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff; })();

try {
  vm.runInContext(src, sandbox, { filename: 'inline-script.js' });
} catch (e) {
  console.error('INIT_FAILED:', e && e.stack || e);
  process.exit(1);
}
console.log('init: ok, queued rAF:', rafQueue.length);

// pump several frames with advancing time
let now = 16;
for (let f = 0; f < 5; f++) {
  const q = rafQueue; rafQueue = [];
  if (q.length === 0) { console.error('NO_FRAME_QUEUED at frame', f); process.exit(1); }
  now += 16;
  try {
    // emulate performance.now advancing
    sandbox.performance.now = () => now;
    q.forEach((cb) => cb(now));
  } catch (e) {
    console.error('FRAME_FAILED:', e && e.stack || e);
    process.exit(1);
  }
}
console.log('frames: 5 ok (init + update/render path exercised)');

// reduced-motion path: re-run with matches:true, expect no rAF loop, one static draw
rafQueue = [];
sandbox.window.matchMedia = () => ({ matches: true });
try {
  vm.runInContext(src, sandbox, { filename: 'inline-script-reduced.js' });
  console.log('reduced-motion: ok, queued rAF:', rafQueue.length, '(expect 0)');
  if (rafQueue.length !== 0) { console.error('REDUCED_MOTION_LOOPED'); process.exit(1); }
} catch (e) {
  console.error('REDUCED_FAILED:', e && e.stack || e);
  process.exit(1);
}
console.log('SMOKE_PASS');
